// Simulasi hasil pemeriksaan port TCP 21 (nmap) untuk localhost
// Tujuan: memahami konsep verifikasi FTP lewat port.

const port = 21;
const host = 'localhost';

// Ubah nilai ini untuk mencoba skenario
const isOpen = true;

if (isOpen) {
  console.log(`nmap: Port ${port}/tcp on ${host} is OPEN (FTP aktif)`);
} else {
  console.log(`nmap: Port ${port}/tcp on ${host} is CLOSED (FTP belum aktif)`);
}

